class TimeMap {
    private Map<String, List<int[]>> map; // key -> list of [timestamp, valueIndex]
    private Map<String, List<String>> values; // key -> list of values

    public TimeMap() {
        map = new HashMap<>();
        values = new HashMap<>();
    }

    public void set(String key, String value, int timestamp) {
        map.computeIfAbsent(key, k -> new ArrayList<>()).add(new int[]{timestamp, values.getOrDefault(key, new ArrayList<>()).size()});
        values.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
    }

    public String get(String key, int timestamp) {
        if (!map.containsKey(key)) return "";

        List<int[]> list = map.get(key);
        int left = 0, right = list.size() - 1;
        int resultIdx = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (list.get(mid)[0] <= timestamp) {
                resultIdx = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        if (resultIdx == -1) return "";
        return values.get(key).get(list.get(resultIdx)[1]);
    }
}

class TimeMap {
    private Map<String, TreeMap<Integer, String>> map;

    public TimeMap() {
        map = new HashMap<>();
    }

    public void set(String key, String value, int timestamp) {
        map.computeIfAbsent(key, k -> new TreeMap<>()).put(timestamp, value);
    }

    public String get(String key, int timestamp) {
        if (!map.containsKey(key)) return "";

        TreeMap<Integer, String> treeMap = map.get(key);
        Integer floorKey = treeMap.floorKey(timestamp);

        return floorKey == null ? "" : treeMap.get(floorKey);
    }
}
